    public int power(int base, int exponent) {
        int product = base;
        if (exponent == 0)
            return 1;

        for (int i = 1; i < exponent; i++) {
            product = product * base;
        }

        return product;
    }



    public int buycp(int hawc, int cfbuncnd) {
        int bpuvkod = hawc;
        if (cfbuncnd == 0)
            return 1;

        for (int i = 1; i < cfbuncnd; i++) {
            bpuvkod = bpuvkod * hawc;
        }

        return bpuvkod;
    }

